1	import tailwindcss, { type Config } from 'tailwindcss';
2	import colors from 'tailwindcss/colors';
3	import postcss from 'postcss';
4	import { test, expect, describe, vi } from 'vitest';
5	import StarlightTailwindPlugin from '..';
6	
7	/** Generate a CSS string based on the passed CSS and HTML content. */
8	const generatePluginCss = ({
9		css = '@tailwind base;',
10		html = '',
11		config = {},
12	}: { css?: string; html?: string; config?: Partial<Config> } = {}): Promise<string> => {
13		return postcss(
14			tailwindcss({
15				// Enable Starlight plugin.
16				plugins: [StarlightTailwindPlugin()],
17				// Provide content for Tailwind to scan for class names.
18				content: [{ raw: html, extension: 'html' }],
19				// Spread in any custom Tailwind config.
20				...config,
21			})
22		)
23			.process(css, { from: '' })
24			.then((result) => result.css);
25	};
26	
27	describe('@tailwind base;', async () => {
28		// Generate base CSS with no core Tailwind plugins running to see just Starlight’s output.
29		const base = await generatePluginCss({ config: { corePlugins: [] } });
