70		`);
71		});
72	
73		test('configures `--sl-color-*` variables', () => {
74			expect(base).includes('--sl-color-gray-1: #e5e7eb;');
75			expect(base).includes('--sl-color-accent: #4f46e5;');
76		});
77	
78		describe('with user theme config', async () => {
79			const baseWithConfig = await generatePluginCss({
80				config: {
81					corePlugins: [],
82					theme: { extend: { colors: { accent: colors.amber, gray: colors.slate } } },
83				},
84			});
85	
86			test('generates different CSS from base without user config', () => {
87				expect(baseWithConfig).not.toEqual(base);
